code.python:
def markers_balanced(text: str, opener: str, closer: str) -> bool:
    depth = 0
    for ch in text:
        if ch == opener:
            depth += 1
        elif ch == closer:
            # A closer with nothing open can never be matched later.
            if depth == 0:
                return False
            depth -= 1
    return depth == 0

code.rust:
fn markers_balanced(text: String, opener: char, closer: char) -> bool {
    let mut depth: usize = 0;
    // `chars()` walks Unicode scalar values; walking bytes would split '«' or '🙂'.
    for ch in text.chars() {
        if ch == opener {
            depth += 1;
        } else if ch == closer {
            // A closer with nothing open can never be matched later.
            if depth == 0 {
                return false;
            }
            depth -= 1;
        }
    }
    depth == 0
}
